// Two-view map: industrial companies and area amenities around one base point.
// Data comes from data/map_data.json, generated by build_map_data.py.

const PALETTE = [
  "#1f77b4", "#d62728", "#2ca02c", "#ff7f0e", "#9467bd",
  "#8c564b", "#e377c2", "#17becf", "#bcbd22", "#393b79",
];
const OTHER_COLOR = "#8c8c8c";
const OTHER = "Other types";
const LABEL_MIN_ZOOM = 15;   // from this zoom, label every pin on screen...
const FEW_PINS = 60;         // ...below it, only when this few pins are on screen
const MAX_LABELS = 250;      // cap on labels drawn at once
const LOGO_SIZE = 30;        // logo pins are this many pixels across
const BASE_SIZE = 38;        // the base point icon is this many pixels across

const map = L.map("map", { preferCanvas: true, maxZoom: 20 });

// Base maps that need no API key. The first is the default; if a map's tiles
// fail to load, the next one is tried automatically.
const OSM_ATTRIBUTION =
  '&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors';
const BASEMAPS = {
  "Street (OpenStreetMap)": L.tileLayer("https://tile.openstreetmap.org/{z}/{x}/{y}.png", {
    maxNativeZoom: 19, maxZoom: 20, attribution: OSM_ATTRIBUTION,
  }),
  "Street (Esri)": L.tileLayer(
    "https://server.arcgisonline.com/ArcGIS/rest/services/World_Street_Map/MapServer/tile/{z}/{y}/{x}", {
      maxNativeZoom: 19, maxZoom: 20,
      attribution: "Tiles &copy; Esri &mdash; Source: Esri, HERE, Garmin, USGS, NGA, and the GIS User Community",
    }),
  "Satellite (Esri)": L.tileLayer(
    "https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}", {
      maxNativeZoom: 19, maxZoom: 20,
      attribution: "Tiles &copy; Esri &mdash; Source: Esri, Maxar, Earthstar Geographics, and the GIS User Community",
    }),
};
const SATELLITE = "Satellite (Esri)";
const BASEMAP_KEY = "basemap";

// Road and place names drawn over the satellite imagery
const ESRI_REFERENCE = "https://server.arcgisonline.com/ArcGIS/rest/services/Reference";
const SATELLITE_LABELS = L.layerGroup([
  L.tileLayer(`${ESRI_REFERENCE}/World_Transportation/MapServer/tile/{z}/{y}/{x}`,
    { maxNativeZoom: 19, maxZoom: 20 }),
  L.tileLayer(`${ESRI_REFERENCE}/World_Boundaries_and_Places/MapServer/tile/{z}/{y}/{x}`,
    { maxNativeZoom: 19, maxZoom: 20 }),
]);
let lastStreetMap = Object.keys(BASEMAPS)[0];

// Keep the satellite labels, the Map/Satellite buttons and the saved choice in step
function afterBasemapChange(name) {
  const satellite = name === SATELLITE;
  if (satellite) SATELLITE_LABELS.addTo(map); else map.removeLayer(SATELLITE_LABELS);
  if (!satellite) lastStreetMap = name;
  document.querySelectorAll("#basemap-toggle button").forEach((b) => {
    b.setAttribute("aria-pressed", String((b.dataset.mode === "satellite") === satellite));
  });
  try { localStorage.setItem(BASEMAP_KEY, name); } catch (e) { /* storage unavailable */ }
}

function useBasemap(name) {
  Object.values(BASEMAPS).forEach((layer) => map.removeLayer(layer));
  BASEMAPS[name].addTo(map);
  afterBasemapChange(name);
}

function setupBasemaps() {
  const names = Object.keys(BASEMAPS);
  let saved = null;
  try { saved = localStorage.getItem(BASEMAP_KEY); } catch (e) { /* storage unavailable */ }
  useBasemap(names.includes(saved) ? saved : names[0]);
  L.control.layers(BASEMAPS, null, { position: "topleft" }).addTo(map);
  map.on("baselayerchange", (e) => afterBasemapChange(e.name));

  document.querySelectorAll("#basemap-toggle button").forEach((b) => {
    b.addEventListener("click", () =>
      useBasemap(b.dataset.mode === "satellite" ? SATELLITE : lastStreetMap));
  });

  // Fallback: a map whose first tiles all fail is swapped for the next one
  names.forEach((name, i) => {
    const layer = BASEMAPS[name];
    let loaded = false, errors = 0;
    layer.on("tileload", () => { loaded = true; });
    layer.on("tileerror", () => {
      errors += 1;
      if (loaded || errors < 4 || i === names.length - 1 || !map.hasLayer(layer)) return;
      console.warn(`Base map "${name}" is unavailable, switching to "${names[i + 1]}"`);
      useBasemap(names[i + 1]);
    });
  });
}
setupBasemaps();

const state = {
  data: null, view: null, views: {}, radiusKm: null, query: "", rings: true,
  pinLayer: L.layerGroup().addTo(map), labelLayer: L.layerGroup().addTo(map),
  radiusCircle: null,
};
const $ = (id) => document.getElementById(id);

function escapeHtml(s) {
  return String(s).replace(/[&<>"']/g, (c) => (
    { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
}

function formatKm(km) {
  return km < 1 ? `${Math.round(km * 1000)} m` : `${km.toFixed(1)} km`;
}

// ── Base point (shared by both views) ────────────────────────────────────────

// The base point uses site/logos/<base.logo> (config.json), or a black diamond
// if there is none or it fails to load
function addBase(base) {
  const diamond = '<div class="base-marker"></div>';
  const [anchorX, anchorY] = base.anchor || [0.5, 0.5];
  const icon = base.logo
    ? L.divIcon({
        className: "",
        html: `<img class="base-logo" src="${escapeHtml(base.logo)}" alt="" ` +
              `onerror="this.outerHTML='${diamond.replace(/"/g, "&quot;")}'">`,
        iconSize: [BASE_SIZE, BASE_SIZE],
        // base.anchor: where on the icon the address is, as fractions of its
        // width and height ([0.5, 0.5] = centre; a map pin's tip is near the bottom)
        iconAnchor: [BASE_SIZE * anchorX, BASE_SIZE * anchorY],
      })
    : L.divIcon({ className: "", html: diamond, iconSize: [22, 22], iconAnchor: [11, 11] });
  L.marker([base.lat, base.lon], { icon, zIndexOffset: 1000 })
    .bindTooltip(escapeHtml(base.name), { permanent: true, direction: "top",
                                          offset: [0, base.logo ? -BASE_SIZE * anchorY - 2 : -14],
                                          className: "base-label" })
    .bindPopup(`<div class="popup"><h3>${escapeHtml(base.name)}</h3>` +
               `<p class="muted">Base point</p><p>${escapeHtml(base.address || "")}</p></div>`)
    .addTo(map);
  state.radiusCircle = L.circle([base.lat, base.lon], {
    radius: 1, color: "#111", weight: 1.5, dashArray: "6 6", fill: false, interactive: false,
  }).addTo(map);
}

// ── Per-view setup: colours by type, one marker per point ────────────────────

function popupHtml(p) {
  const base = state.data.base;
  const rating = p.rating != null
    ? `<p>★ ${p.rating.toFixed(1)}${p.reviews != null ? ` (${p.reviews.toLocaleString()} reviews)` : ""}</p>`
    : "";
  const link = p.place_id
    ? `<p><a href="https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(p.name)}` +
      `&query_place_id=${encodeURIComponent(p.place_id)}" target="_blank" rel="noopener">` +
      `Open in Google Maps</a></p>`
    : "";
  return `<div class="popup"><h3>${escapeHtml(p.name)}</h3>` +
         `<p class="muted">${escapeHtml(p.type)}${p.source ? ` · ${escapeHtml(p.source)}` : ""}</p>` +
         (p.address ? `<p>${escapeHtml(p.address)}</p>` : "") + rating +
         `<p class="muted">${formatKm(p.km)} from ${escapeHtml(base.name)}</p>${link}</div>`;
}

// Logo pins: each view's logo from site/logos (config.json "logo"), framed in
// the place's type colour when rings are on. A view without a logo uses dots.
function logoIcon(src, color) {
  return L.divIcon({
    className: "",
    html: `<div class="logo-pin" style="border-color:${color}">` +
          `<img src="${escapeHtml(src)}" alt="" onerror="this.remove()"></div>`,
    iconSize: [LOGO_SIZE, LOGO_SIZE],
    iconAnchor: [LOGO_SIZE / 2, LOGO_SIZE / 2],
  });
}

// Colour of a pin's ring (logo pins) or fill (dots): the type colour when rings
// are shown; otherwise no ring, and dots take their dataset's colour
function pinColor(it, typeColor) {
  if (state.rings) return typeColor;
  return it.logo ? "#fff" : it.datasetColor;
}

function setupView(key, view) {
  const items = view.points.map((p) => {
    // Logo URLs come from the build (versioned, e.g. logos/industrial.svg?v=...).
    // In the combined view each point carries its own logo and colour.
    const logo = (p.logo !== undefined ? p.logo : view.logo) || null;
    const marker = logo
      ? L.marker([p.lat, p.lon], { icon: logoIcon(logo, OTHER_COLOR) })
      : L.circleMarker([p.lat, p.lon], {
          radius: 7, color: "#fff", weight: 1.5, fillColor: OTHER_COLOR, fillOpacity: 0.9,
        });
    return {
      p, logo, marker, color: OTHER_COLOR, datasetColor: p.color || view.color || OTHER_COLOR,
      group: OTHER,
      labelOffset: logo ? -(LOGO_SIZE / 2 + 2) : -6,
      search: `${p.name} ${p.type} ${p.address}`.toLowerCase(),
    };
  });
  items.forEach((it) => {
    it.marker.bindPopup(() => popupHtml(it.p));
    it.marker.bindTooltip(`<span class="name">${escapeHtml(it.p.name)}</span>`,
      { direction: "top", offset: [0, it.labelOffset], className: "pin-label" });
  });
  state.views[key] = { items, groups: [], colors: {}, counts: {}, hidden: new Set() };
}

// The most common types within the current radius get their own colour,
// the rest share grey as "Other types"
function assignColors() {
  const v = state.views[state.view];
  const inRange = v.items.filter((it) => it.p.km <= state.radiusKm);
  const typeCounts = {};
  inRange.forEach((it) => { typeCounts[it.p.type] = (typeCounts[it.p.type] || 0) + 1; });
  const top = Object.keys(typeCounts)
    .sort((a, b) => typeCounts[b] - typeCounts[a] || a.localeCompare(b))
    .slice(0, PALETTE.length);
  v.colors = Object.fromEntries(top.map((t, i) => [t, PALETTE[i]]));
  v.colors[OTHER] = OTHER_COLOR;

  v.counts = {};
  v.items.forEach((it) => {
    it.group = it.p.type in v.colors ? it.p.type : OTHER;
    const color = pinColor(it, v.colors[it.group]);
    if (color === it.color) return;
    it.color = color;
    if (it.logo) it.marker.setIcon(logoIcon(it.logo, color));
    else it.marker.setStyle({ fillColor: color });
  });
  inRange.forEach((it) => { v.counts[it.group] = (v.counts[it.group] || 0) + 1; });
  v.groups = v.counts[OTHER] ? [...top, OTHER] : top;
}

// ── Filtering and drawing ────────────────────────────────────────────────────

function visibleItems() {
  const v = state.views[state.view];
  const q = state.query;
  return v.items.filter((it) =>
    it.p.km <= state.radiusKm && !v.hidden.has(it.group) && (!q || it.search.includes(q)));
}

function draw() {
  state.pinLayer.clearLayers();
  const shown = visibleItems();
  shown.forEach((it) => state.pinLayer.addLayer(it.marker));
  state.shown = shown;
  $("count").textContent = `${shown.length.toLocaleString()} shown`;
  renderLegend();
  drawLabels();
}

// Permanent name labels for pins on screen, when they would not bury the map
function drawLabels() {
  state.labelLayer.clearLayers();
  if (!$("show-labels").checked || !state.shown) return;
  const bounds = map.getBounds();
  const onScreen = state.shown.filter((it) => bounds.contains(it.marker.getLatLng()));
  if (onScreen.length > FEW_PINS && map.getZoom() < LABEL_MIN_ZOOM) return;
  onScreen
    .slice(0, MAX_LABELS)
    .forEach((it) => {
      L.tooltip({ permanent: true, direction: "top", offset: [0, it.labelOffset],
                  className: "pin-label", interactive: false })
        .setLatLng(it.marker.getLatLng())
        .setContent(`<span class="name">${escapeHtml(it.p.name)}</span>`)
        .addTo(state.labelLayer);
    });
}

function renderLegend() {
  const v = state.views[state.view];
  $("legend-items").innerHTML =
    `<label><span class="swatch base"></span>${escapeHtml(state.data.base.name)}</label>` +
    v.groups.map((g, i) =>
      `<label><input type="checkbox" data-i="${i}" ${v.hidden.has(g) ? "" : "checked"}>` +
      `<span class="swatch" style="background:${v.colors[g]}"></span>${escapeHtml(g)}` +
      `<span class="count">${v.counts[g]}</span></label>`).join("");

  $("legend-items").querySelectorAll("input[data-i]").forEach((box) => {
    box.addEventListener("change", () => {
      const g = v.groups[Number(box.dataset.i)];
      if (box.checked) v.hidden.delete(g); else v.hidden.add(g);
      draw();
    });
  });
}

function fitToRadius() {
  // Computed from the base point: the circle has no bounds until the map has a view
  const { lat, lon } = state.data.base;
  map.fitBounds(L.latLng(lat, lon).toBounds(state.radiusKm * 2000), { padding: [20, 20] });
}

// Print / PDF: hide the controls, let the map fill the page, wait for the
// map tiles at the new size, then open the browser's print dialog
function printMap() {
  document.body.classList.add("printing");
  map.invalidateSize();
  let done = false;
  const go = () => {
    if (done) return;
    done = true;
    window.print();
  };
  Object.values(BASEMAPS).forEach((layer) => { if (map.hasLayer(layer)) layer.once("load", go); });
  setTimeout(go, 2500);
}

window.addEventListener("afterprint", () => {
  document.body.classList.remove("printing");
  map.invalidateSize();
});

function setRadius(km, fit = true) {
  state.radiusKm = km;
  state.radiusCircle.setRadius(km * 1000);
  if (fit) fitToRadius();
  assignColors();
  draw();
}

function showView(key) {
  if (!state.views[key]) key = Object.keys(state.views)[0];
  state.view = key;
  map.closePopup();
  document.querySelectorAll("#tabs button").forEach((b) => {
    b.setAttribute("aria-selected", String(b.dataset.view === key));
  });
  $("legend-title").textContent = state.data.views[key].label;
  if (location.hash !== `#${key}`) history.replaceState(null, "", `#${key}`);
  assignColors();
  draw();
}

// ── Start-up ─────────────────────────────────────────────────────────────────

async function init() {
  let data;
  try {
    const res = await fetch("data/map_data.json", { cache: "no-cache" });
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    data = await res.json();
  } catch (e) {
    $("map").innerHTML =
      `<p class="error">Could not load data/map_data.json (${escapeHtml(e.message)}).</p>`;
    return;
  }
  state.data = data;
  document.title = data.title;
  $("title").textContent = data.title;

  addBase(data.base);
  Object.entries(data.views).forEach(([key, view]) => {
    setupView(key, view);
    const btn = document.createElement("button");
    btn.type = "button";
    btn.role = "tab";
    btn.dataset.view = key;
    btn.textContent = view.label;
    btn.addEventListener("click", () => showView(key));
    $("tabs").appendChild(btn);
  });

  const radius = $("radius");
  data.radius_options_km.forEach((km) => {
    radius.add(new Option(`Within ${km} km`, km, false, km === data.default_radius_km));
  });
  radius.addEventListener("change", () => setRadius(Number(radius.value)));

  let timer;
  $("search").addEventListener("input", (e) => {
    clearTimeout(timer);
    timer = setTimeout(() => { state.query = e.target.value.trim().toLowerCase(); draw(); }, 150);
  });
  $("show-labels").addEventListener("change", drawLabels);
  $("show-radius").addEventListener("change", (e) => {
    if (e.target.checked) state.radiusCircle.addTo(map); else map.removeLayer(state.radiusCircle);
  });
  $("show-rings").addEventListener("change", (e) => {
    state.rings = e.target.checked;
    document.body.classList.toggle("no-rings", !state.rings);
    assignColors();
    draw();
  });
  $("print").addEventListener("click", printMap);
  if (window.matchMedia("(max-width: 600px)").matches) $("legend-box").open = false;
  map.on("moveend", drawLabels);
  window.addEventListener("hashchange", () => showView(location.hash.slice(1)));

  state.view = Object.keys(state.views)[0];
  setRadius(data.default_radius_km);
  showView(location.hash.slice(1));
}

init();
